package com.slcm.portal;
import org.junit.jupiter.api.Test; import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest; import org.springframework.boot.test.mock.mockito.MockBean; import org.springframework.security.test.context.support.WithMockUser; import org.springframework.test.web.servlet.MockMvc; import org.springframework.beans.factory.annotation.Autowired; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
@WebMvcTest(controllers=RoleTestController.class) class RoleAuthorizationWebTest { @Autowired MockMvc mvc; @MockBean com.slcm.portal.auth.JwtAuthenticationFilter jwtFilter; @Test @WithMockUser(roles="STUDENT") void studentCannotAccessAdmin() throws Exception {mvc.perform(get("/api/test/admin")).andExpect(status().isForbidden());} @Test @WithMockUser(roles="ADMIN") void adminCanAccessAdmin() throws Exception {mvc.perform(get("/api/test/admin")).andExpect(status().isOk());} }
